"""Save original context, ambient bindings and unresolved source conventions."""
import json
from save_inventory import ROOT,PID

def main():
    aux=[]
    def add(n,s,pages,note,deps=()):aux.append(dict(local_id='A'+str(n),statement_original=s,evidence=[dict(page=p,location='Original main-text context A'+str(n)) for p in pages],scope_note=note,depends_on=list(deps)))
    add(1,r'''One iteration of such an algorithm takes the current state $x\in\mathbb R^d$, transforms to $\mathbb S^d\setminus N$ through inverse stereographic projection, carrying out an appropriately constructed MCMC step on $\mathbb S^d\setminus N$ before returning to $\mathbb R^d$ by stereographic projection.''',[2],'North-pole exclusion in the overall sampler setup. Later initialization on the full sphere requires a boundary convention.',['D1'])
    add(2,r'''PDMPs utilise an auxiliary random variable $v$, which in the case of the Stereographic Bouncy Particle Sampler (SBPS) has stationary distribution uniformly distributed on $\mathbb S^d$ and independently of $x$. One feature of PDMP algorithms such as SBPS is the option to include refresh moves that contribute to the intensity of their constituting point process (according to some possibly $x$-dependent hazard rate) and which independently refresh $v$ by sampling it from its invariant distribution (uniform on $\mathbb S^d$). In the description below, we restrict ourselves to the case where this refresh rate is constant.''',[8],'Original velocity and constant-refresh prose. Its full-sphere independent velocity claim differs from Algorithm2 tangent-sphere refreshment. Neither is silently substituted for the other.',['D5'])
    add(3,r'''Suppose that $\lambda_{\mathrm{refresh}}>0$ and $\pi>0$ for all $x\in\mathbb R^d$. Then SBPS gives rise to an ergodic Markov chain on $\mathbb R^d$ with invariant distribution for $(x,v)$ with joint density on $\mathbb R^d\times\mathbb S^d$. The marginal density on $\mathbb R^d$ is proportional to $\pi(x)$.''',[9],'Full Proposition2.2 body, stored as auxiliary context rather than a Theorem. It explicitly assumes positive refreshment. Its velocity/state-space wording remains as printed. T2.2 does not explicitly cite this proposition as a hypothesis.',['D5'])
    add(4,r'''We shall thus assume $R$ to be scaled in this way in what follows. Therefore, we consider $R=\sqrt{\lambda d}$ for a fixed constant $\lambda$.''',[16],'Section5 radius convention. Positivity follows the radius parameter domain; Theorems5.1/5.2 select R=sqrt(d), hence lambda=1.',['D1','D12'])
    add(5,r'''Note that the difference between SPS and RSPS is that in RSPS two independent proposals $\widehat X'$ and $\widehat X''$ are first computed. Then the final proposal is composed by the first coordinate of $\widehat X'$ and other coordinates of $\widehat X''$, i.e., $\widehat X:=(\widehat X'_1,\widehat X''_{2:d})$. This design guarantees $\widehat X_1$ is independent with $\widehat X_{2:d}$ conditional on the current state, which is the technical condition needed to prove the following result on a diffusion limit.''',[19],'Original two-proposal and coordinate-splicing description; contrasts with the unprimed leading increments printed in Algorithm4. Independence is conditional on the current state.',['D14'])
    add(6,r'''$\Phi(\cdot)$ being the standard Gaussian cumulative density function.''',[20],'Original wording within T5.2. Phi is interpreted as a Gaussian cumulative distribution function in the ambient analysis; original wording is preserved.')
    add(7,r'''A reasonable conjecture is that the same diffusion limit holds for the original SPS algorithm. In order to establish the same diffusion limit, if we follow the same arguments as in the proof of Theorem 5.1, it is required to show the acceptance rate term becomes “asymptotically independent” with the first coordinate as a rate of $O(d^{-1/2})$. However, our current technical arguments in Theorem 5.1 can achieve a rate of $O(d^{-1/8})$ which is not enough for establishing the weak convergence to a diffusion limit. Therefore, we only prove the diffusion limit for RSPS in this paper and leave the proof for SPS as an open problem.''',[20,21],'Complete Remark5.6, excluding the proof itself. This is an explicit limit on the scope of T5.2, not an extra theorem or a premise of T5.1.',['D3','D14'])
    add(8,r'''First, we just consider a random-walk Metropolis algorithm with a step size $h$ on the unit sphere. Note that we describe our algorithms on the unit sphere. The radius $R$ will only be taken into account when projecting to $\mathbb R^d$.''',[6],'Step size is on the unit sphere; R enters the stereographic map. A positive, finite proposal scale is an algorithm domain convention, not an invented inequality in T2.1.',['D1','D3'])
    add(9,r'''Furthermore, as $\mathbb E[\|\widehat X-X\|^2]\to\ell^2$, we obtain the commonly used approximation of Expected Squared Jumping Distance (ESJD):
\[
\mathbb E[\|\widehat X-X\|^2]\cdot\mathbb E\left[1\wedge\frac{\pi(\widehat X)(R^2+\|\widehat X\|^2)^d}{\pi(X)(R^2+\|X\|^2)^d}\right]\to2\ell^2\cdot\Phi\left(-\frac\ell2\sqrt{\mathbb E_f\left[((\log f)')^2\right]-\frac{4\lambda}{(1+\lambda)^2}}\right).\tag{16}
\]''',[17],'The source explicitly calls this a product-of-expectations approximation. Definition5.1 is instead a joint expectation; the approximation is not substituted into T5.1.',['D3','D12'])
    add(10,r'''In Fig. 4, we show the proposed SBPS without and with refreshment for standard Gaussian target in two dimensions. Note that the SBPS without refreshment is not irreducible in this case. The same issue exists for the Euclidean BPS for standard Gaussian targets. This issue can be fixed by adding the refreshment.''',[10],'Example2.2 explicitly identifies the zero-refresh issue. It supports recording the positive-refresh domain convention without inserting an unprinted theorem hypothesis.',['D5'])
    issues=ISSUES
    bindings={
'T2.1':'A fixed-dimensional positive continuous probability density pi on R^d, a positive radius R and the SPS transition kernel with a nondegenerate positive proposal scale h. Original discrete-time uniform ergodicity is equivalent to the displayed finite supremum. The condition is an inline theorem predicate; pi_S need not be imported as a separate algebraic dependency because Algorithm1 prints its ratio directly. Norm, supremum, total variation and invariant probability are ambient.',
'T2.2':'A positive target density with continuous first partial derivatives, the SBPS process using pi_S and the constant-refresh algorithm, and continuous-time uniform ergodicity. The limsup radial-score bound is strictly below1/2. Refreshment and augmented velocity domain conventions are separately documented; no conjectured bound1 or geometric-ergodicity replacement is inserted.',
'T4.1':'A sequence of diagonal-covariance Gaussian targets pi_(mu,Sigma), the ordinary SPS proposal, stationary X, and dimension-uniform c,C bounds on eigenvalues and means. R=sqrt(d), alpha<=1 and the moment-mismatch O(d^alpha) condition are bound inside the theorem. Its stepsize is o of a minimum, preserving the additional exponent restriction. No adaptive GSPS, rotation matrix, isotropy, product-normalization or Section5.1 conditions are imported.',
'T5.1':'SPS started in its stationary law, product target pi=product f with fixed marginal f, the complete Section5.1 normalization/moment/score/full-support conditions, and f different from the standard Gaussian density. R=sqrt(d), lambda=1 and fixed ell use the Eq15 stepsize convention. ESJD is the exact joint stationary expectation in Definition5.1. Phi is the standard Gaussian cumulative distribution; score-square expectation and square root are ambient operations. Neither Eq16 approximation nor a corollary optimum becomes part of the theorem.',
'T5.2':'RSPS rather than original SPS, with the same Section5.1 product target and all marginal conditions, f nonstandard Gaussian, stationary initial law and R=sqrt(d). Ell uses the continuing Eq15 convention, not an explicit repeated reference in the printed theorem. U^d is the first coordinate accelerated by d and piecewise constant through floor(dt). The limit is a real-valued Langevin SDE with Brownian driver, score drift and displayed speed s(ell), in the named Skorokhod topology. The natural initial marginal is f from stationarity; path-space/J1 and initial-driver conventions are ambient interpretations, not added source text. No proved diffusion result for original SPS is inferred.'}
    refs=[]
    def ref(n,target,kind,note):refs.append(dict(claim_id=PID+'/T'+n,target=target,reference_kind=kind,note=note))
    ref('2.1','Algorithm1 and preceding discrete-time uniform-ergodicity definition','definition_reference','Use the original SPS transition and common-time total-variation definition. Proposition2.1 is not an extra theorem hypothesis.')
    ref('2.2','Algorithm2 and preceding continuous-time uniform-ergodicity definition','definition_reference','Retain the actual refresh and tangent-reflection algorithm; preserve the positive-rate context separately.')
    ref('4.1','Section4.2 Gaussian target and Algorithm1 SPS proposal','definition_reference','The expected ratio uses the ordinary SPS proposal. Section4.1 GSPS is motivation, not a required definition for the bound.')
    for n in ['5.1','5.2']:ref(n,'Section5.1, including the full-support paragraph after Remark5.1','assumption_reference','Product density, second and sixth moments, Lipschitz score, boundary derivative limit, all three integrability conditions and full support are retained separately.')
    ref('5.1','Eq.(15) with lambda=1 and Definition5.1','definition_reference','Fixed-ell stepsize and exact joint-expectation ESJD, not its earlier approximation.')
    ref('5.2','Algorithm4 and continuing Eq.(15) convention','definition_reference','RSPS coordinate splice and section-wide scaling. Eq15 is not explicitly repeated in the original theorem.')
    for n,sec in [('2.1','S8.2'),('2.2','S8.4'),('4.1','S8.8'),('5.1','S8.10'),('5.2','S8.11')]:ref(n,'Section '+sec,'proof_only','Supplementary proof body is outside the reading scope. It supplies no imported statement dependency.')
    data=dict(paper_id=PID,unranked_auxiliary_passages=aux,statement_local_bindings=bindings,source_claim_references=refs,source_issues=issues,unresolved_external_prerequisites=[],ambient_prerequisites=['Euclidean vectors, inner products and norms, unit spheres and tangent spaces, densities and probability kernels, Gaussian and exponential distributions, projections and Jacobian change of variables.','Discrete-time Markov kernels and continuous-time semigroups, invariant probabilities, total variation and uniform ergodicity, deterministic flows, gradients, time-inhomogeneous Poisson event hazards and refreshment.','Dimension-indexed product densities, expectations, derivative ratios, Lipschitz continuity, support, asymptotic O/o notation, minima/maxima, limits and integration.','Brownian motion, Langevin stochastic differential equations, initial laws, weak convergence in the named Skorokhod topology and first-coordinate acceleration. The usual real-valued cadlag path-space interpretation is analysis context; it is not a verbatim additional theorem hypothesis. No mathlib availability claim.'],validation_limits='Main-text source census only. All original Theorems and their required local source passages are retained. Supplementary proofs, correctness of the original algorithms and unresolved source conventions are not certified by schema validation.')
    (ROOT/'ambient-prerequisites.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')

ISSUES=[{'issue_id': 'registered-source-scope', 'evidence': [{'page': 1, 'location': 'Version stamp'}, {'page': 24, 'location': 'Acknowledgement and main-text endpoint'}], 'note': 'Registered arXiv2205.12112v2, marked21Feb2024,80pages. Main text ends on24; supplementary proofs starting25 and simulations starting62 are excluded. Five Theorems are retained.'}, {'issue_id': 'source-issue-1', 'evidence': [{'page': 8, 'location': 'SBPS velocity space'}], 'note': 'Prose says v is uniform on S^d independently of x; Algorithm2 constrains v perpendicular to z and uniform on the unit tangent sphere. Preserve algorithm and archive conflicting prose separately; do not identify those laws.'}, {'issue_id': 'source-issue-2', 'evidence': [{'page': 9, 'location': 'Refreshment rate and state space'}], 'note': 'Theorem2.2 does not explicitly repeat Proposition2.2 positivity of lambda_refresh. Algorithm2 samples Exponential(lambda_refresh); record its positive-rate domain as an algorithm convention, not an unprinted theorem clause. Uniform ergodicity may refer to augmented process versus projected x; preserve source ambiguity.'}, {'issue_id': 'source-issue-3', 'evidence': [{'page': 8, 'location': 'SBPS initialization and evaluation conventions'}], 'note': 'Algorithm2 initializes on all S^d, whereas SP and pi_S omit north pole. Reflection has zero denominator if tangent gradient is zero, normally zero bounce intensity. The stopping instruction exits at the first event beyond T without explicit interpolation back to T. Preserve source; do not repair via supplementary proof.'}, {'issue_id': 'source-issue-4', 'evidence': [{'page': 14, 'location': 'Gaussian mismatch bound'}], 'note': 'Theorem4.1 has denominator sqrt(max(mean absolute eigenvalue deviations, mean squared means)) and an additional minimum with d^{-(1/2 vee alpha)}. Exact standard Gaussian makes the denominator zero; note limiting convention is unstated. No generalized-projection algorithm is required to state this theorem.'}, {'issue_id': 'source-issue-5', 'evidence': [{'page': 15, 'location': 'Surrounding Gaussian examples'}], 'note': 'Example4.3 prints lambda_i=0 although Theorem4.1 assumes positive eigenvalues. The final paragraph twice says acceptance goes to zero under an o stepsize condition, contradicting the theorem convergence to1. These are surrounding examples, not theorem repairs or additional assumptions.'}, {'issue_id': 'source-issue-6', 'evidence': [{'page': 16, 'location': 'Section5.1 scope'}], 'note': 'Second moment equals1; mean zero is not assumed. Sixth-moment finiteness is substantive despite without-loss-of-generality wording. Full support is stated after Remark5.1. The ratios f-prime/f and f-double-prime/f require pointwise/domain conventions beyond a bare topological support statement.'}, {'issue_id': 'source-issue-7', 'evidence': [{'page': 17, 'location': 'Scaling branch'}], 'note': 'Equation15 requires d>1 and an admissible radicand. Its displayed implication assumes 1-(ell^2/2d)*4lambda/(1+lambda)^2 positive, since the square root otherwise produces an absolute value. Fixed ell and positive lambda meet this eventually. Archive the R=sqrt(lambda*d) convention from page16 separately.'}, {'issue_id': 'source-issue-8', 'evidence': [{'page': 19, 'location': 'ESJD versus approximation'}], 'note': 'Definition5.1 is the joint expectation of squared proposal displacement times acceptance. Equation16 is a product-of-expectations approximation, not its definition. Only the former belongs to Theorem5.1. The 0.234 optimum is a corollary and must not be merged into the theorem.'}, {'issue_id': 'source-issue-9', 'evidence': [{'page': 20, 'location': 'RSPS printed increments'}], 'note': 'Algorithm4 prints unprimed d-tilde-z as the leading term in both primed tangent increments. The preceding prose says two independent SPS proposals, with coordinate splice (X-prime_1,X-double-prime_2:d). Preserve literal formula and archive intended independence prose separately.'}, {'issue_id': 'source-issue-10', 'evidence': [{'page': 20, 'location': 'RSPS stationary law and proposal ratio'}], 'note': 'Do not certify that the coordinate-spliced proposal has the same Hastings ratio as original SPS merely because that acceptance ratio is printed. Source theorem assumes stationarity. Proof is outside scope; preserve algorithm and record this as an unresolved mathematical verification question, not a claimed disproof.'}, {'issue_id': 'source-issue-11', 'evidence': [{'page': 20, 'location': 'Diffusion scope and bindings'}], 'note': 'Theorem5.2 is RSPS only; original SPS analogue is conjectured in Remark5.6. It uses ell without repeating Eq15; retain the continuing section scaling as context. U initial law f follows stated stationary initial marginal; Brownian driver and Skorokhod path-space conventions should be recorded as ambient, not invented source quotations. Preserve original cumulative density function wording for Phi.'}, {'issue_id': 'source-issue-12', 'evidence': [{'page': 16, 'location': 'Ancillary Fisher-information examples'}], 'note': 'Remark5.1 and Table1 concern a rescaled Student-t example, not required for the five theorem statements. Do not import its C_nu formula, truncated-Gaussian equality example or table into the theorem dependency graph. In particular finite sixth moment excludes many example degrees of freedom.'}, {'issue_id': 'nondegenerate-sps-scale', 'evidence': [{'page': 6, 'location': 'Algorithm1 Gaussian proposal'}, {'page': 7, 'location': 'Theorem2.1'}], 'note': 'Theorem2.1 does not print a scale restriction. Algorithm1 must use a positive finite h for the intended nondegenerate sampler; at h=0 it is an identity chain. Record that domain convention separately, not as an added original theorem clause.'}]
if __name__=='__main__':main()
